class Solution {
public:
    string intToRoman(int num) {
        vector<int> vals = {1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1};
        vector<string> syms = {"M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"};
        string res;
        for (int k = 0; k < (int)vals.size(); k++) {
            while (num >= vals[k]) {
                res += syms[k];
                num -= vals[k];
            }
        }
        return res;
    }
};
